<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue';import P6Dialog from './P6Dialog.vue';import {amountCents,money} from './tradeAmounts';
type Row={id:string;[k:string]:any};type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
const props=defineProps<{section:'invoices'|'expenses'|'funds';request:Request;readonly:boolean;access:any;manager:boolean;memberId:string}>();
const busy=ref(false),error=ref(''),success=ref(''),rows=ref<Row[]>([]),accounts=ref<Row[]>([]),contracts=ref<Row[]>([]),total=ref(0),page=ref(1),q=ref(''),dialog=ref(''),selected=ref<Row|null>(null),history=ref<Row[]>([]),entries=ref<Row[]>([]),entryPage=ref(1),entryTotal=ref(0),accountTotal=ref(0),unallocated=ref(0),key=ref('');
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const form=reactive({name:'',accountReference:'',amount:'',date:today,contractId:'',title:'',buyerName:'',taxNumber:'',notes:'',accountId:'',payee:'',category:'',reference:'',reason:''});
const labels:Record<string,string>={DRAFT:'草稿',SUBMITTED:'待审核',APPROVED:'已批准',ISSUED:'已开票',VOID:'已作废',CONFIRMED:'已确认',REVERSED:'已冲正',OPENING:'期初余额',RECEIPT:'回款到账',RECEIPT_REVERSAL:'回款冲正',EXPENSE:'支出',EXPENSE_REVERSAL:'支出冲正',CREATED:'新建',SUBMIT:'提交审核',APPROVE:'批准',REJECT:'退回',ISSUE:'登记发票',RED:'红冲',CONFIRM:'确认支出',REVERSE:'冲正',ACTIVATED:'启用',DISABLED:'停用'};
const title=computed(()=>({invoices:'开票协同',expenses:'支出管理',funds:'资金台账'})[props.section]);const canReview=computed(()=>!props.readonly&&props.manager&&props.access.confirm);const canWrite=computed(()=>!props.readonly&&props.access.receiptWrite);
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){if(props.section==='funds'){const r=await props.request<any>('/finance/accounts');rows.value=r.items;accounts.value=r.items;accountTotal.value=r.items.reduce((n:number,a:Row)=>n+Number(a.balanceCents),0);unallocated.value=r.unallocatedReceivedCents;total.value=r.items.length;}else{const path=props.section==='invoices'?`/finance/invoices?page=${page.value}&pageSize=20&q=${encodeURIComponent(q.value)}`:`/finance/expenses?page=${page.value}&pageSize=20`;const r=await props.request<any>(path);rows.value=r.items;total.value=r.total;}}
function reset(){Object.assign(form,{name:'',accountReference:'',amount:props.section==='funds'?'0.00':'',date:today,contractId:'',title:'',buyerName:'',taxNumber:'',notes:'',accountId:'',payee:'',category:'',reference:'',reason:''});key.value=crypto.randomUUID();}
function create(){run(async()=>{reset();selected.value=null;if(props.section==='invoices'){const r=await props.request<any>('/contracts?page=1&pageSize=100&collectable=true');contracts.value=r.items;}else if(props.section==='expenses'){const r=await props.request<any>('/finance/account-options');accounts.value=r.items;}dialog.value='create';});}
function chooseContract(){const c=contracts.value.find(x=>x.id===form.contractId);if(c){form.title=c.title;form.buyerName=c.customerNameSnapshot;}}
function centsSigned(value:string){if(!/^-?\d+(\.\d{1,2})?$/.test(value))throw new Error('金额最多两位小数');const negative=value.startsWith('-');const raw=value.replace('-','');return (negative?-1:1)*(Number(raw)===0?0:amountCents(raw));}
function save(){run(async()=>{const common={notes:form.notes};let payload:any,path='';if(props.section==='invoices'){path='/finance/invoices';payload={...common,contractId:form.contractId,title:form.title,buyerName:form.buyerName,taxNumber:form.taxNumber,amountCents:amountCents(form.amount)};}else if(props.section==='expenses'){path='/finance/expenses';payload={...common,accountId:form.accountId,payee:form.payee,category:form.category,amountCents:amountCents(form.amount),paymentDate:form.date,paymentReference:form.reference};}else{path='/finance/accounts';payload={name:form.name,accountReference:form.accountReference,openingCents:centsSigned(form.amount),openingDate:form.date};}await props.request(path,'POST',payload,{'Idempotency-Key':key.value});dialog.value='';await load();success.value='已保存';});}
async function detail(row:Row){selected.value=props.section==='invoices'?await props.request<Row>('/finance/invoices/'+row.id):row;const type=props.section==='invoices'?'INVOICE':props.section==='expenses'?'EXPENSE':'ACCOUNT';const h=await props.request<any>(`/finance/history/${type}/${row.id}`);history.value=h.items;dialog.value='view';}
function view(row:Row){run(()=>detail(row));}
function action(act:string){if(!selected.value)return;reset();dialog.value=act;}
function apply(){run(async()=>{const r=selected.value!,act=dialog.value;const body={expectedVersion:r.version,reason:form.reason,reference:form.reference||null,businessDate:form.date,amountCents:act==='red'?amountCents(form.amount):null};const updated=await props.request<Row>(`/finance/${props.section}/${r.id}/${act}`,'POST',body,{'Idempotency-Key':key.value});await load();await detail(updated);success.value='操作已保存并留存历史';});}
function ledger(row:Row){run(async()=>{selected.value=row;entryPage.value=1;await loadEntries();dialog.value='ledger';});}
async function loadEntries(){const r=await props.request<any>(`/finance/accounts/${selected.value!.id}/entries?page=${entryPage.value}&pageSize=20`);entries.value=r.items;entryTotal.value=r.total;}
function turn(n:number){page.value+=n;run(load);}function entriesTurn(n:number){entryPage.value+=n;run(loadEntries);}
function toggle(row:Row){run(async()=>{await props.request('/finance/accounts/'+row.id,'PUT',{active:!row.active,expectedVersion:row.version});await load();success.value='账户状态已更新，已有流水保留';});}
watch(()=>props.section,()=>{page.value=1;dialog.value='';selected.value=null;run(load);});onMounted(()=>run(load));
</script>
<template><section class="p6"><div class="page-heading"><div><span class="eyebrow">FINANCE WORKSPACE</span><h1>{{title}}</h1><p>{{section==='invoices'?'申请、复核、开票与红冲，关联订单和合同。':section==='expenses'?'登记付款，复核确认后计入资金流水。':'查看资金账户及每笔收支的来源和余额。'}}</p></div><button v-if="section==='funds'?canReview:canWrite" class="btn primary" :disabled="busy" @click="create">{{section==='invoices'?'新建开票申请':section==='expenses'?'登记支出':'新建资金账户'}}</button></div><div v-if="section==='funds'" class="p6-kpis"><article><small>资金账户</small><strong>{{total}}</strong></article><article><small>台账余额合计</small><strong>{{money(accountTotal)}}</strong></article><article><small>历史未归集净回款</small><strong>{{money(unallocated)}}</strong></article></div><p v-if="section==='funds'" class="p6-muted">余额按期初与已确认收支流水计算。历史未关联账户的回款单独列示；台账不连接银行、不发起付款。账户为人民币口径。</p><div v-if="error&&!dialog" class="p6-error" role="alert">{{error}}</div><div v-if="success" class="p6-success" role="status">{{success}}</div><form class="p6-toolbar" @submit.prevent="page=1;run(load)"><label v-if="section==='invoices'">搜索<input v-model="q" placeholder="申请编号、主题或合同编号" maxlength="100"/></label><button class="btn secondary" :disabled="busy">查询 / 刷新</button></form><div class="p6-card"><div class="table-scroll"><table><thead><tr><th>{{section==='funds'?'账户':'单据'}}</th><th>{{section==='invoices'?'合同 / 客户':section==='expenses'?'收款方 / 类别':'账户标识'}}</th><th>状态</th><th>{{section==='funds'?'当前余额':'金额'}}</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.invoiceNumber||r.expenseNumber||r.name}}<small>{{r.title||r.accountName}}</small></td><td>{{r.contractNumber||r.payee||r.accountReference||'—'}}<small>{{r.customerNameSnapshot||r.category}}</small></td><td>{{section==='funds'?(r.active?'启用':'停用'):labels[r.status]}}</td><td>{{money(section==='funds'?r.balanceCents:r.amountCents)}}<small v-if="r.redCents">已红冲 {{money(r.redCents)}}</small></td><td><button class="text-button" @click="view(r)">详情</button><template v-if="section==='funds'"><button class="text-button" @click="ledger(r)">流水</button><button v-if="canReview" class="text-button" @click="toggle(r)">{{r.active?'停用':'启用'}}</button></template></td></tr><tr v-if="!rows.length"><td colspan="5">{{busy?'正在读取…':'暂无记录'}}</td></tr></tbody></table></div><div v-if="section!=='funds'" class="p6-pages"><span>共 {{total}} 条 · 第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page===1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=total" @click="turn(1)">下一页</button></div></div>
<P6Dialog v-if="dialog" :title="dialog==='create'?'新增'+title:dialog==='view'?'单据详情':dialog==='ledger'?'账户流水':labels[dialog.toUpperCase()]||'处理单据'" :busy="busy" @close="!busy&&(dialog='')"><div v-if="error" class="p6-error" role="alert">{{error}}</div><template v-if="dialog==='view'&&selected"><div class="p6-grid"><div><small>编号 / 账户</small><p>{{selected.invoiceNumber||selected.expenseNumber||selected.name}}</p></div><div><small>金额 / 余额</small><p>{{money(selected.amountCents??selected.balanceCents)}}</p></div><div v-if="section==='invoices'"><small>抬头 / 税号</small><p>{{selected.buyerName}} · {{selected.taxNumber||'未填'}}</p></div><div><small>凭证 / 日期</small><p>{{selected.invoiceReference||selected.paymentReference||selected.accountReference||'—'}} · {{selected.issuedDate||selected.paymentDate||'—'}}</p></div></div><p class="p6-copy">{{selected.notes}}</p><div v-if="!readonly" class="p6-actions"><template v-if="section==='invoices'"><button v-if="selected.status==='DRAFT'&&selected.createdByMemberId===memberId&&canWrite" class="btn primary" @click="action('submit')">提交审核</button><template v-if="selected.status==='SUBMITTED'&&canReview"><button class="btn primary" @click="action('approve')">批准</button><button class="btn secondary" @click="action('reject')">退回</button></template><button v-if="selected.status==='APPROVED'&&canReview" class="btn primary" @click="action('issue')">登记实际发票</button><button v-if="selected.status==='ISSUED'&&selected.redCents<selected.amountCents&&canReview" class="btn secondary" @click="action('red')">登记红冲</button><button v-if="['DRAFT','SUBMITTED','APPROVED'].includes(selected.status)&&(selected.createdByMemberId===memberId||canReview)&&canWrite" class="btn secondary" @click="action('void')">作废申请</button></template><template v-if="section==='expenses'"><button v-if="selected.status==='DRAFT'&&canReview" class="btn primary" @click="action('confirm')">复核确认</button><button v-if="selected.status==='DRAFT'&&selected.createdByMemberId===memberId&&canWrite" class="btn secondary" @click="action('void')">作废</button><button v-if="selected.status==='CONFIRMED'&&canReview" class="btn secondary" @click="action('reverse')">冲正</button></template></div><p v-if="section==='invoices'" class="p6-muted">同一合同支持分次申请；未开票申请占用额度。开票登记记录实际发票信息，红冲保留原发票。</p><div v-for="r in selected.reds||[]" :key="r.id" class="p6-record">红冲 {{money(r.amountCents)}} · {{r.redReference}} · {{r.reason}}</div><h3>操作历史</h3><div v-for="h in history" :key="h.businessVersion" class="p6-record">v{{h.businessVersion}} · {{labels[h.action]||h.action}} · {{h.actorName}}<small class="p6-muted"> {{h.createdAt}} · {{h.reason}}</small></div></template>
<template v-else-if="dialog==='ledger'"><div class="table-scroll"><table><thead><tr><th>日期 / 来源</th><th>凭证</th><th>变动</th><th>当笔后余额</th></tr></thead><tbody><tr v-for="r in entries" :key="r.id"><td>{{r.businessDate}}<small>{{labels[r.sourceType]}}</small></td><td>{{r.reference}}<small>{{r.notes}}</small></td><td>{{money(r.deltaCents)}}</td><td>{{money(r.balanceCents)}}</td></tr></tbody></table></div><div class="p6-pages"><span>共 {{entryTotal}} 笔 · 第 {{entryPage}} 页</span><button class="btn secondary" :disabled="busy||entryPage===1" @click="entriesTurn(-1)">上一页</button><button class="btn secondary" :disabled="busy||entryPage*20>=entryTotal" @click="entriesTurn(1)">下一页</button></div></template>
<form v-else @submit.prevent="dialog==='create'?save():apply()"><fieldset :disabled="busy||readonly"><template v-if="dialog==='create'"><template v-if="section==='invoices'"><label>合同<select v-model="form.contractId" required @change="chooseContract"><option value="">选择已签合同</option><option v-for="c in contracts" :key="c.id" :value="c.id">{{c.contractNumber}} · {{c.customerNameSnapshot}}</option></select></label><div class="p6-grid"><label>申请主题<input v-model="form.title" required maxlength="200"/></label><label>发票抬头<input v-model="form.buyerName" required maxlength="200"/></label><label>税号<input v-model="form.taxNumber" maxlength="80"/></label><label>申请金额（元）<input v-model="form.amount" required inputmode="decimal"/></label></div></template><template v-else-if="section==='expenses'"><label>付款账户<select v-model="form.accountId" required><option value="">请选择</option><option v-for="a in accounts.filter(x=>x.active)" :key="a.id" :value="a.id">{{a.name}}</option></select></label><div class="p6-grid"><label>收款方<input v-model="form.payee" maxlength="200" required/></label><label>支出类别<input v-model="form.category" maxlength="80" placeholder="差旅、采购、服务等" required/></label><label>付款金额（元）<input v-model="form.amount" required inputmode="decimal"/></label><label>付款日期<input v-model="form.date" type="date" :max="today" required/></label></div><label>付款凭证号<input v-model="form.reference" maxlength="120" required/></label></template><template v-else><label>账户名称<input v-model="form.name" maxlength="100" required/></label><label>账户标识<input v-model="form.accountReference" maxlength="120" placeholder="可填写银行及账号尾号"/></label><div class="p6-grid"><label>期初余额（元）<input v-model="form.amount" required inputmode="decimal"/></label><label>期初日期<input v-model="form.date" type="date" :max="today" required/></label></div></template><label v-if="section!=='funds'">备注<textarea v-model="form.notes" maxlength="2000" rows="3"/></label></template><template v-else><p>{{selected?.invoiceNumber||selected?.expenseNumber}} · {{labels[selected?.status]}}</p><p class="p6-muted">{{dialog==='confirm'||dialog==='approve'?'审核人必须与登记人为不同账号。':dialog==='red'||dialog==='reverse'?'冲正保留原单据和历史。':''}}</p><template v-if="['issue','red'].includes(dialog)"><label>{{dialog==='red'?'红字发票号码':'实际发票号码'}}<input v-model="form.reference" required maxlength="120"/></label><label v-if="dialog==='red'">红冲金额（元）<input v-model="form.amount" inputmode="decimal" required/></label></template><label v-if="['issue','red','reverse'].includes(dialog)">业务日期<input v-model="form.date" type="date" :max="today" required/></label><label>原因 / 核对备注<textarea v-model="form.reason" rows="3" maxlength="500" :required="['void','red','reverse','reject'].includes(dialog)"/></label></template></fieldset><div class="p6-actions"><button type="button" class="btn secondary" :disabled="busy" @click="dialog=selected?'view':''">返回</button><button class="btn primary" :disabled="busy||readonly">{{busy?'处理中…':'确认保存'}}</button></div></form></P6Dialog></section></template>
